DROP TABLE IF EXISTS `md_project`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `md_project` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tenant_id` bigint NOT NULL COMMENT '租户ID【多租户隔离字段】',
  `company_id` bigint NOT NULL COMMENT '所属公司ID',
  `project_code` varchar(64) NOT NULL COMMENT '项目编码',
  `project_name` varchar(200) NOT NULL COMMENT '项目名称',
  `project_type` varchar(50) DEFAULT NULL COMMENT '项目类型(取字典 project_type)',
  `dept_id` bigint DEFAULT NULL COMMENT '承担部门ID',
  `manager_id` bigint DEFAULT NULL COMMENT '项目经理用户ID',
  `begin_date` date DEFAULT NULL COMMENT '开始日期',
  `end_date` date DEFAULT NULL COMMENT '结束日期',
  `total_budget` decimal(20,2) DEFAULT '0.00' COMMENT '项目总预算',
  `used_amount` decimal(20,2) DEFAULT '0.00' COMMENT '已使用金额',
  `status` varchar(20) NOT NULL DEFAULT 'NORMAL' COMMENT '状态:NORMAL在建/FINISHED已结项/DISABLED停用',
  `remark` varchar(500) DEFAULT NULL,
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_project_code` (`tenant_id`,`project_code`),
  KEY `idx_tenant` (`tenant_id`),
  KEY `idx_tenant_company` (`tenant_id`,`company_id`)
) ENGINE=InnoDB AUTO_INCREMENT=87 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='项目';
